mapper.select:
SELECT INTERF_ID interfId, INTERF_NAME interfName, INTERF_TYPE interfType, INTERF_STS interfSts, INTERF_TERMTRC interfTermtrc, MSG_BODY msgBody, SEND_FLG sendFlg, SEND_COUNT sendCount, CREATE_USER createUser, CREATE_DEPT createDept, CREATE_TIME createTime, UPDATE_USER updateUser, UPDATE_TIME updateTime FROM INTERF_STS
AND INTERF_STS = #{interfSts,jdbcType=VARCHAR}
AND INTERF_ID LIKE '%' || #{interfId} || '%'
AND TO_CHAR(CREATE_TIME , 'YYYY-MM-DD') >= #{beginTime}
AND #{endTime}>=TO_CHAR(CREATE_TIME , 'YYYY-MM-DD')
